<template><section class="surface-effect-picker"><h3>表面效果</h3><div role="radiogroup" aria-label="表面效果"><button v-for="option in CARD_SURFACE_OPTIONS" :key="option.id" type="button" :class="{ 'is-active': active === option.id }" @click="$emit('update', option.id)">{{ option.label }}</button></div></section></template>
<script setup>import { computed } from 'vue'; import { CARD_SURFACE_OPTIONS } from '../cardSurface.js'; const props = defineProps({ style: { type:Object, default:()=>({}) } }); defineEmits(['update']); const active = computed(() => props.style.backdropBlur ? 'glass' : props.style.background === 'rgba(255,255,255,0.10)' ? 'transparent' : props.style.background === 'rgba(255,255,255,0.78)' ? 'translucent' : 'standard')</script>
<style scoped>.surface-effect-picker{display:grid;gap:6px}.surface-effect-picker h3{margin:8px 0 0;font-size:12px}.surface-effect-picker>div{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.surface-effect-picker button{min-height:28px;border:1px solid #cbd8dd;border-radius:5px;background:#fff;color:#38505c;cursor:pointer;font-size:11px}.surface-effect-picker button.is-active{border-color:#1261a6;background:#eaf5ff;color:#1261a6;font-weight:600}</style>
